-- seed_initial_data.sql
-- Initial master data for pyquant (SQLite)
-- Intended to be executed AFTER create_tables.sql


PRAGMA foreign_keys = ON;
BEGIN TRANSACTION;


ON CONFLICT(role) DO UPDATE SET
  description=excluded.description
;

ON CONFLICT(interp_method) DO UPDATE SET
  description=excluded.description
;

ON CONFLICT(extrap_method) DO UPDATE SET
  description=excluded.description
;

ON CONFLICT(product) DO UPDATE SET
  description=excluded.description
;

ON CONFLICT(ccy) DO UPDATE SET
  name=excluded.name, iso_numeric=excluded.iso_numeric, minor_unit=excluded.minor_unit, symbol=excluded.symbol, spot_lag=excluded.spot_lag, enabled=excluded.enabled, valid_from=excluded.valid_from, retired_at=excluded.retired_at
;

ON CONFLICT(code) DO UPDATE SET
  display_name=excluded.display_name, formula_tag=excluded.formula_tag, notes=excluded.notes, enabled=excluded.enabled
;

ON CONFLICT(code) DO UPDATE SET
  display_name=excluded.display_name, rule_tag=excluded.rule_tag, nearest_tiebreaker=excluded.nearest_tiebreaker, notes=excluded.notes, enabled=excluded.enabled
;

ON CONFLICT(cal_id) DO UPDATE SET
  display_name=excluded.display_name, time_zone=excluded.time_zone, enabled=excluded.enabled
;

ON CONFLICT(ccy, role) DO UPDATE SET
  cal_id=excluded.cal_id, enabled=excluded.enabled
;

-- market_holiday: 15 years ahead (2026-2040), approximate sets

ON CONFLICT(cal_id, holiday) DO UPDATE SET
  holiday_name=excluded.holiday_name, holiday_type=excluded.holiday_type, observed_of=excluded.observed_of, is_half_day=excluded.is_half_day, notes=excluded.notes, enabled=excluded.enabled
;

ON CONFLICT(cal_id, holiday) DO UPDATE SET
  holiday_name=excluded.holiday_name, holiday_type=excluded.holiday_type, observed_of=excluded.observed_of, is_half_day=excluded.is_half_day, notes=excluded.notes, enabled=excluded.enabled
;

ON CONFLICT(cal_id, holiday) DO UPDATE SET
  holiday_name=excluded.holiday_name, holiday_type=excluded.holiday_type, observed_of=excluded.observed_of, is_half_day=excluded.is_half_day, notes=excluded.notes, enabled=excluded.enabled
;

ON CONFLICT(cal_id, holiday) DO UPDATE SET
  holiday_name=excluded.holiday_name, holiday_type=excluded.holiday_type, observed_of=excluded.observed_of, is_half_day=excluded.is_half_day, notes=excluded.notes, enabled=excluded.enabled
;

ON CONFLICT(cal_id, holiday) DO UPDATE SET
  holiday_name=excluded.holiday_name, holiday_type=excluded.holiday_type, observed_of=excluded.observed_of, is_half_day=excluded.is_half_day, notes=excluded.notes, enabled=excluded.enabled
;

ON CONFLICT(cal_id, holiday) DO UPDATE SET
  holiday_name=excluded.holiday_name, holiday_type=excluded.holiday_type, observed_of=excluded.observed_of, is_half_day=excluded.is_half_day, notes=excluded.notes, enabled=excluded.enabled
;

ON CONFLICT(cal_id, holiday) DO UPDATE SET
  holiday_name=excluded.holiday_name, holiday_type=excluded.holiday_type, observed_of=excluded.observed_of, is_half_day=excluded.is_half_day, notes=excluded.notes, enabled=excluded.enabled
;

ON CONFLICT(index_id) DO UPDATE SET
  ccy=excluded.ccy, tenor=excluded.tenor, daycount=excluded.daycount, display_name=excluded.display_name, index_family=excluded.index_family, rate_type=excluded.rate_type, fixing_cal_id=excluded.fixing_cal_id, fixing_bdc=excluded.fixing_bdc, fixing_time_local=excluded.fixing_time_local, fixing_tz=excluded.fixing_tz, publication_lag_days=excluded.publication_lag_days, accrual_conv=excluded.accrual_conv, lookback_days=excluded.lookback_days, lockout_days=excluded.lockout_days, source_tag=excluded.source_tag, enabled=excluded.enabled, valid_from=excluded.valid_from, retired_at=excluded.retired_at
;

ON CONFLICT(vendor_id) DO UPDATE SET
  display_name=excluded.display_name, enabled=excluded.enabled, note=excluded.note
;

ON CONFLICT(curve_id) DO UPDATE SET
  ccy=excluded.ccy, curve_type=excluded.curve_type, ref_rate_id=excluded.ref_rate_id, daycount=excluded.daycount, compounding=excluded.compounding, compounding_freq=excluded.compounding_freq, interp_method=excluded.interp_method, extrap_left=excluded.extrap_left, extrap_right=excluded.extrap_right, pillar_mode=excluded.pillar_mode, build_method=excluded.build_method, cal_id=excluded.cal_id, collateral_ccy=excluded.collateral_ccy, valid_from=excluded.valid_from, valid_to=excluded.valid_to, description=excluded.description
;

ON CONFLICT(fut_code) DO UPDATE SET
  display_name=excluded.display_name, exchange_code=excluded.exchange_code, ccy=excluded.ccy, underlying_ref_rate_id=excluded.underlying_ref_rate_id, contract_notional=excluded.contract_notional, tick_size=excluded.tick_size, tick_value=excluded.tick_value, quote_conv=excluded.quote_conv, last_trading_bdc=excluded.last_trading_bdc, last_trading_cal_id=excluded.last_trading_cal_id, notes=excluded.notes, enabled=excluded.enabled
;

ON CONFLICT(security_id) DO UPDATE SET
  isin=excluded.isin, local_code=excluded.local_code, name=excluded.name, issuer=excluded.issuer, ccy=excluded.ccy, coupon_type=excluded.coupon_type, coupon_rate=excluded.coupon_rate, float_index_id=excluded.float_index_id, float_spread=excluded.float_spread, coupon_daycount=excluded.coupon_daycount, coupon_freq=excluded.coupon_freq, coupon_bdc=excluded.coupon_bdc, coupon_cal_id=excluded.coupon_cal_id, redemption=excluded.redemption, issue_date=excluded.issue_date, maturity_date=excluded.maturity_date, first_coupon_date=excluded.first_coupon_date, last_coupon_date=excluded.last_coupon_date, settlement_days=excluded.settlement_days, settlement_bdc=excluded.settlement_bdc, settlement_cal_id=excluded.settlement_cal_id, prospectus_uri=excluded.prospectus_uri
;


COMMIT;
